import type { Ratings } from "@features/stands/lib/survey-input";

export const QUEUED_VISITS_API_PATH = "/api/stand/queued-visits";

/** A batch carries at most 50 visits (RF-35); the server refuses a bigger one. */
export const MAX_QUEUE_BATCH = 50;

const RETRY_BASE_MS = 1000;

const RETRY_MAX_MS = 60_000;

/** A visit the kiosk took without connection. The ratings only travel to the server; the kiosk never shows them. */
export interface QueuedVisit {
  /** Generated by the kiosk: a batch sent twice does not record the visit twice. */
  id: string;
  pin: string;
  ratings: Ratings;
  /** When the kiosk took the PIN, as an ISO 8601 instant (RN-04). */
  scannedAt: string;
}

/** What the server answers for each visit of a batch. `ok` and `duplicate` leave the queue as sent. */
export type QueuedVisitStatus = "ok" | "duplicate" | QueuedVisitRefusal;

export type QueuedVisitRefusal = "late" | "unknownVisitor" | "standWithoutGame" | "invalid";

export interface QueuedVisitResult {
  id: string;
  status: QueuedVisitStatus;
}

/** A visit the server did not record, with its reason; the kiosk lists it under "No registradas". */
export interface RejectedQueuedVisit {
  id: string;
  reason: QueuedVisitRefusal;
  scannedAt: string;
}

/** Where the kiosk keeps the queue: IndexedDB in the browser, memory in the tests. */
export interface VisitQueueStore {
  listPending: () => Promise<QueuedVisit[]>;
  addPending: (visit: QueuedVisit) => Promise<void>;
  removePending: (ids: string[]) => Promise<void>;
  listRejected: () => Promise<RejectedQueuedVisit[]>;
  addRejected: (visits: RejectedQueuedVisit[]) => Promise<void>;
}

export interface SettledBatch {
  /** Visits that leave the queue: sent, already recorded or refused. */
  settledIds: string[];
  rejected: RejectedQueuedVisit[];
}

const REFUSALS: readonly QueuedVisitStatus[] = ["late", "unknownVisitor", "standWithoutGame", "invalid"];

/** The queue in batches of at most 50, in the order the PINs were taken. */
export function buildBatches(pending: QueuedVisit[]): QueuedVisit[][] {
  const ordered = [...pending].sort((left, right) => left.scannedAt.localeCompare(right.scannedAt));
  const batches: QueuedVisit[][] = [];

  for (let start = 0; start < ordered.length; start += MAX_QUEUE_BATCH) {
    batches.push(ordered.slice(start, start + MAX_QUEUE_BATCH));
  }

  return batches;
}

/** Applies the answer of the server to a batch. A visit the answer leaves out stays in the queue for the next try. */
export function settleBatch(batch: QueuedVisit[], results: QueuedVisitResult[]): SettledBatch {
  const statusById = new Map(results.map((result) => [result.id, result.status]));
  const answered = batch.filter((visit) => statusById.has(visit.id));

  return {
    settledIds: answered.map((visit) => visit.id),
    rejected: answered.flatMap((visit) => toRejected(visit, statusById.get(visit.id))),
  };
}

/**
 * How long to wait before the next try: exponential backoff with "equal jitter", so the kiosks that come back online at
 * the same time do not hit the server together, and the wait still grows with each failure (RF-35).
 */
export function getRetryDelay(attempt: number, random: () => number = Math.random): number {
  const ceiling = Math.min(RETRY_MAX_MS, RETRY_BASE_MS * 2 ** Math.max(attempt - 1, 0));

  return Math.round(ceiling / 2 + random() * (ceiling / 2));
}

/** A random id for a queued visit; `randomUUID` only exists on HTTPS, so the kiosk on a LAN address builds its own. */
export function createVisitId(): string {
  if (globalThis.isSecureContext) return crypto.randomUUID();

  const bytes = crypto.getRandomValues(new Uint8Array(16));

  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;

  const hex = [...bytes].map((byte) => byte.toString(16).padStart(2, "0")).join("");

  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function toRejected(visit: QueuedVisit, status: QueuedVisitStatus | undefined): RejectedQueuedVisit[] {
  return isQueuedVisitRefusal(status) ? [{ id: visit.id, reason: status, scannedAt: visit.scannedAt }] : [];
}

function isQueuedVisitRefusal(status: QueuedVisitStatus | undefined): status is QueuedVisitRefusal {
  return status !== undefined && REFUSALS.includes(status);
}
